import{_ as o,o as r,c as t,a6 as a}from"./chunks/framework.QBF2cGGQ.js";const m=JSON.parse('{"title":"05 · 微调与对齐","description":"","frontmatter":{},"headers":[],"relativePath":"guide/05-finetune.md","filePath":"guide/05-finetune.md","lastUpdated":1793329740000}'),n={name:"guide/05-finetune.md"};function i(p,s,l,g,e,u){return r(),t("div",null,[...s[0]||(s[0]=[a('<h1 id="_05-·-微调与对齐" tabindex="-1">05 · 微调与对齐 <a class="header-anchor" href="#_05-·-微调与对齐" aria-label="Permalink to &quot;05 · 微调与对齐&quot;">​</a></h1><blockquote><p><strong>投入权重：5%</strong> · 刻意压低权重。九成需求用 RAG + prompt 解决，微调是最后手段。 但你要知道什么时候真的必须微调，以及它有多贵。</p></blockquote><h2 id="为什么权重这么低" tabindex="-1">为什么权重这么低 <a class="header-anchor" href="#为什么权重这么低" aria-label="Permalink to &quot;为什么权重这么低&quot;">​</a></h2><p>微调是转岗者最容易高估的技能。原因很直观：它听起来最&quot;AI&quot;，最像算法工程师干的事，也最容易在简历上写。但真实项目里，微调解决的是很窄的一类问题：固定风格、固定格式、领域黑话、以及把大模型能力压进小模型降本。</p><p>如果你发现&quot;模型不懂我们业务&quot;，八成是检索没做好、prompt 没写清、或者评测集根本没建。这时候去微调，等于用最贵的方式解决一个本来免费的 bug。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to &quot;决策&quot;">​</a></h2><ul><li><strong>微调 / RAG / Prompt 决策树</strong> <span class="prio prio-must">必须</span> — 知识不足→RAG；格式不稳→结构化输出或微调；风格不对→微调；降本→蒸馏小模型。</li><li><strong>必须微调的四种情况</strong> <span class="prio prio-must">必须</span> — 固定输出风格、极短 prompt 要求（降本）、领域黑话、把大模型能力蒸馏进小模型。</li><li><strong>不该微调的典型误判</strong> <span class="prio prio-must">必须</span> — &quot;模型不懂我们业务&quot;——八成是检索没做好，不是模型不行。</li><li><strong>微调的隐性成本</strong> <span class="prio prio-must">必须</span> — 数据标注 + 训练 + 评估 + 每次基座升级要重做。这条常被低估。</li><li><strong>对照实验原则</strong> <span class="prio prio-must">必须</span> — 决定微调前，先用同等时间做一版 RAG + prompt 方案，两者对比。没有对照就没有结论。</li></ul><h2 id="数据" tabindex="-1">数据 <a class="header-anchor" href="#数据" aria-label="Permalink to &quot;数据&quot;">​</a></h2><ul><li><strong>SFT 数据格式</strong> <span class="prio prio-must">必须</span> — chat 格式（多轮）vs instruct 格式（单轮）。按推理时的真实格式构造，格式不一致会掉效果。</li><li><strong>质量远大于数量</strong> <span class="prio prio-must">必须</span> — 500 条高质量 &gt; 50000 条脏数据。先去重、去噪、去矛盾。</li><li><strong>数据多样性</strong> <span class="prio prio-must">必须</span> — 覆盖边界情况与不同表达方式，否则模型学成复读机。</li><li><strong>合成数据生成</strong> <span class="prio prio-imp">重要</span> — 用强模型生成 + 人工校验。当前主流做法，但要注意&quot;模型味&quot;污染。</li><li><strong>标注流程与规范</strong> <span class="prio prio-imp">重要</span> — 先写标注手册，再做一致性检验（双人标注比对），否则数据不可用。</li><li><strong>训练集与评测集隔离</strong> <span class="prio prio-must">必须</span> — 同一来源的样本不能跨集，否则指标虚高。</li><li><strong>数据配比</strong> <span class="prio prio-imp">重要</span> — 混入 10~30% 通用数据，防止灾难性遗忘。</li><li><strong>数据长度分布</strong> <span class="prio prio-imp">重要</span> — 训练数据长度要接近推理时的实际长度，差距过大会导致截断或效果下降。</li></ul><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><ul><li><strong>LoRA 原理</strong> <span class="prio prio-must">必须</span> — 低秩分解，只训练少量参数。理解 rank / alpha 的物理意义。</li><li><strong>LoRA 超参</strong> <span class="prio prio-must">必须</span> — rank 8~64、alpha 常为 rank 的 2 倍、dropout 0.05。小数据用小 rank。</li><li><strong>QLoRA</strong> <span class="prio prio-must">必须</span> — 4bit 量化基座 + LoRA，单卡可微调大模型。个人开发者首选。</li><li><strong>全参微调</strong> <span class="prio prio-opt">选学</span> — 成本高，仅在数据量大且需要深度改造时用。</li><li><strong>学习率与 warmup</strong> <span class="prio prio-imp">重要</span> — LoRA 常用 1e-4 ~ 2e-4，warmup 3~5%。</li><li><strong>灾难性遗忘</strong> <span class="prio prio-must">必须</span> — 微调后通用能力下降。解法：混入通用数据 + 保留通用评测集。</li><li><strong>DPO / ORPO / KTO</strong> <span class="prio prio-imp">重要</span> — 偏好优化，不需要奖励模型。适合&quot;风格对齐&quot;而非&quot;知识注入&quot;。</li><li><strong>蒸馏</strong> <span class="prio prio-imp">重要</span> — 强模型生成高质量回答训练小模型，降本主力。</li><li><strong>过拟合识别</strong> <span class="prio prio-must">必须</span> — 训练 loss 降但验证集不降，或输出开始千篇一律。</li></ul><h2 id="对齐与强化学习-了解即可" tabindex="-1">对齐与强化学习（了解即可） <a class="header-anchor" href="#对齐与强化学习-了解即可" aria-label="Permalink to &quot;对齐与强化学习（了解即可）&quot;">​</a></h2><p>这一层你大概率不会自己跑，但<strong>面试问&quot;为什么推理模型要用 RL&quot;答不出来，会显得只懂上层</strong>。知道每样东西解决什么问题就够了。</p><ul><li><strong>RLHF 三段式</strong> <span class="prio prio-imp">重要</span> — SFT → 训奖励模型（人类偏好打分）→ 用 PPO 优化策略。<strong>问题：训练不稳定、要四个模型同时在显存里、贵</strong>。</li><li><strong>Reward Model（奖励模型）</strong> <span class="prio prio-imp">重要</span> — 学会&quot;人类更喜欢哪个回答&quot;。它的偏差会被策略模型放大（reward hacking）。<strong>这就是&quot;过度讨好&quot;和&quot;过度拒答&quot;的来源</strong>。</li><li><strong>PPO</strong> <span class="prio prio-opt">选学</span> — 经典 RL 算法，需要 critic 模型和价值估计。工程复杂。</li><li><strong>DPO</strong> <span class="prio prio-must">必须</span> — 直接用偏好对（chosen / rejected）优化，<strong>跳过奖励模型和 RL 循环</strong>。工程上简单得多，是当前开源微调主流。</li><li><strong>ORPO / KTO / SimPO</strong> <span class="prio prio-imp">重要</span> — DPO 的变体：ORPO 把 SFT 和偏好优化合成一步；KTO 只需要&quot;好/坏&quot;标签不需要成对；SimPO 去掉参考模型省显存。</li><li><strong>GRPO</strong> <span class="prio prio-imp">重要</span> — DeepSeek 用的方法：<strong>同一问题采样多个答案，用组内相对得分当优势</strong>，省掉 critic 模型。<strong>这是推理模型（R1 系）能训出来的关键</strong>。</li><li><strong>可验证奖励（RLVR）</strong> <span class="prio prio-imp">重要</span> — 数学题对答案、代码跑单测——<strong>奖励来自程序验证而不是人类偏好</strong>。这是推理能力提升的核心机制，也是&quot;为什么数学和代码先突破&quot;的原因。</li><li><strong>对齐税（Alignment Tax）</strong> <span class="prio prio-imp">重要</span> — 对齐后模型变&quot;安全&quot;但也变&quot;保守&quot;，创造性和多样性下降。<strong>产品上表现为&quot;回答越来越像模板&quot;</strong>。</li><li><strong>过度拒答</strong> <span class="prio prio-imp">重要</span> — 安全训练过度导致正常问题被拒。<strong>这是 ToB 落地最常见的抱怨</strong>，解法是补充&quot;该答的必须答&quot;的正样本。</li><li><strong>你实际会做的</strong> <span class="prio prio-must">必须</span> — 不是训 RL，而是<strong>构造偏好数据跑 DPO</strong>：同一个问题收集&quot;好答案/差答案&quot;对，几百到几千条，DPO 一轮。这是应用工程师能独立完成的对齐工作。</li></ul><h2 id="工具链" tabindex="-1">工具链 <a class="header-anchor" href="#工具链" aria-label="Permalink to &quot;工具链&quot;">​</a></h2><ul><li><strong>LLaMA-Factory</strong> <span class="prio prio-must">必须</span> — 国内最常用的一站式微调框架，WebUI 友好。</li><li><strong>Unsloth</strong> <span class="prio prio-imp">重要</span> — 显存与速度优化明显，单卡友好。</li><li><strong>Axolotl</strong> <span class="prio prio-opt">选学</span> — 配置化，适合批量实验。</li><li><strong>PEFT / TRL / DeepSpeed</strong> <span class="prio prio-imp">重要</span> — 底层库，需要定制时用。</li><li><strong>合并与导出</strong> <span class="prio prio-imp">重要</span> — LoRA 合并回基座、转 GGUF 供本地推理。</li></ul><h2 id="评估" tabindex="-1">评估 <a class="header-anchor" href="#评估" aria-label="Permalink to &quot;评估&quot;">​</a></h2><ul><li><strong>微调效果评估</strong> <span class="prio prio-must">必须</span> — 必须同时看&quot;目标任务提升&quot;和&quot;通用能力保持&quot;两组指标。</li><li><strong>与 RAG 方案对比</strong> <span class="prio prio-must">必须</span> — 花同样时间做 RAG 是不是更好？先做这个对照实验再决定微调。</li><li><strong>回归测试</strong> <span class="prio prio-imp">重要</span> — 微调模型上线前要跑完整评测集，不能只看几个样例。</li><li><strong>成本对比</strong> <span class="prio prio-imp">重要</span> — 自部署小模型的固定成本 vs 调 API 的边际成本，要算出交叉点。</li></ul>',18)])])}const q=o(n,[["render",i]]);export{m as __pageData,q as default};
